#!/usr/bin/env bash
# Prints deploy/docker-compose.demo.yml (`task gen` writes it, `task lint` checks it): the one-file demo
# with the published image of the newest CHANGELOG version and the deploy/seed/ scripts inlined, so it
# works after downloading only that file.
set -euo pipefail
cd "$(dirname "$0")/.."

version=$(sed -n 's/^## v\([0-9][0-9.]*\).*/\1/p' CHANGELOG.md | head -1)

cat <<EOF
# Gresbase demo: PostgreSQL with sample data and five Gresbase instances, one per way of using it.
# Generated by scripts/demo-compose.sh from deploy/seed/ (edit those, then run \`task gen\`).
#
#   curl -fsSLO https://raw.githubusercontent.com/amtzespinosa/gresbase/main/deploy/docker-compose.demo.yml
#   docker compose -f docker-compose.demo.yml up -d
#   docker compose -f docker-compose.demo.yml down -v     # stop and remove everything
#
#   http://localhost:8080  no login (only answers to localhost)
#   http://localhost:8081  login demo / demo
#   http://localhost:8082  read-only
#   http://localhost:8083  setup wizard; the token: docker compose -f docker-compose.demo.yml exec gresbase-setup /gresbase setup-token
#                          the database server is "db" (user and password gresbase, database app)
#   http://localhost:8084  free mode: server db, user and password gresbase, database app
name: gresbase-demo

x-gresbase: &gresbase
  image: ghcr.io/amtzespinosa/gresbase:${version}
  restart: unless-stopped
  depends_on:
    db:
      condition: service_healthy

services:
  db:
    image: postgres:17
    environment:
      POSTGRES_USER: gresbase
      POSTGRES_PASSWORD: gresbase
      POSTGRES_DB: app
    configs:
EOF
for f in deploy/seed/*.sql; do
  n=$(basename "$f")
  printf '      - source: %s\n        target: /docker-entrypoint-initdb.d/%s\n' "${n%.sql}" "$n"
done
cat <<'EOF'
    volumes:
      - demo-pgdata:/var/lib/postgresql/data
    healthcheck:
      # TCP so it only reports healthy once the init scripts have finished
      test: ["CMD-SHELL", "pg_isready -h 127.0.0.1 -U gresbase -d app"]
      interval: 2s
      timeout: 3s
      retries: 60

  gresbase:
    <<: *gresbase
    ports: ["127.0.0.1:8080:8080"]
    environment:
      DATABASE_URL: postgres://gresbase:gresbase@db:5432/app?sslmode=disable
    volumes: [demo-data:/data]

  gresbase-login:
    <<: *gresbase
    ports: ["127.0.0.1:8081:8080"]
    environment:
      DATABASE_URL: postgres://gresbase:gresbase@db:5432/app?sslmode=disable
      GRESBASE_USER: demo
      GRESBASE_PASSWORD: demo
    volumes: [demo-data-login:/data]

  gresbase-ro:
    <<: *gresbase
    ports: ["127.0.0.1:8082:8080"]
    environment:
      DATABASE_URL: postgres://gresbase:gresbase@db:5432/app?sslmode=disable
      GRESBASE_READ_ONLY: "true"
    volumes: [demo-data-ro:/data]

  gresbase-setup:
    <<: *gresbase
    ports: ["127.0.0.1:8083:8080"]
    volumes: [demo-data-setup:/data]

  gresbase-free:
    <<: *gresbase
    ports: ["127.0.0.1:8084:8080"]
    environment:
      GRESBASE_MODE_FREE: "true"
      GRESBASE_ALLOWED_DB_HOSTS: db
    volumes: [demo-data-free:/data]

volumes:
  demo-pgdata:
  demo-data:
  demo-data-login:
  demo-data-ro:
  demo-data-setup:
  demo-data-free:

# deploy/seed/*.sql, with "$" doubled because Compose interpolates it.
configs:
EOF
for f in deploy/seed/*.sql; do
  n=$(basename "$f")
  printf '  %s:\n    content: |\n' "${n%.sql}"
  sed -e 's/\$/$$/g' -e 's/^\(.\)/      \1/' "$f"
done
